import sympy as sp
x = sp.symbols('x', real=True)
def count(c):
    sols = set()
    for s in sp.solve(x**2 - 4 - c, x) + sp.solve(x**2 - 4 + c, x):
        if s.is_real and abs(s**2 - 4) == c:
            sols.add(sp.nsimplify(s))
    return len(sols)
cases = {-1: 0, -sp.Rational(1, 2): 0, 0: 2, 1: 4, 2: 4, sp.Rational(7, 2): 4, 4: 3, 5: 2, 10: 2}
for c, n in cases.items():
    assert count(sp.nsimplify(c)) == n, (c, count(c))
assert sp.solve(x**2 - 8, x) == [-2*sp.sqrt(2), 2*sp.sqrt(2)]

from fractions import Fraction as F
f = lambda t: 1/(1 - t)
assert f(F(0)) == 1
try:
    f(F(1)); raise AssertionError('f(1) should be undefined')
except ZeroDivisionError:
    pass
for t in (F(2), F(-3, 7), F(5, 2), F(1, 3), F(-10)):
    assert f(f(f(t))) == t
